// Runtime for the guest-memory native build of the rw::physics solver job
// (rwphysics_guest.inc, generated by tools/gen_guest.py). Used inside a ReXGlue recomp:
// data stays big-endian in guest memory (base + address), and every vector op is the same
// simde/rex::ppc call the recompiler emits, in the recomp's register layout (the 16 bytes of
// a VMX register reversed, so host lane 0 = guest w). Results therefore match the recompiled
// functions bit for bit, including NaN signs, whatever the build's SIMD flags (FMA etc.).
#pragma once
#include <rex/ppc/context.h>
#include <rex/ppc/intrinsics.h>
#include <bit>
#include <cmath>
#include <cstdint>
#include <cstring>

namespace rwp {

using u32 = uint32_t;
using s32 = int32_t;
using u16 = uint16_t;
using u8 = uint8_t;
using s8 = int8_t;
using __vector4 = simde__m128;

// ---- guest memory ------------------------------------------------------------------------
#define LD_U32(a) __builtin_bswap32(*(const u32 *)(base + (u32)(a)))
#define LD_U16(a) __builtin_bswap16(*(const u16 *)(base + (u32)(a)))
#define LD_U8(a) (*(const u8 *)(base + (u32)(a)))
#define LD_F32(a) std::bit_cast<float>(LD_U32(a))
#define ST_U32(a, v) (*(u32 *)(base + (u32)(a)) = __builtin_bswap32((u32)(v)))
#define ST_U16(a, v) (*(u16 *)(base + (u32)(a)) = __builtin_bswap16((u16)(v)))
#define ST_U8(a, v) (*(u8 *)(base + (u32)(a)) = (u8)(v))
#define ST_F32(a, v) ST_U32(a, std::bit_cast<u32>((float)(v)))

static inline simde__m128i rwp_mask(u32 k) { return simde_mm_load_si128((const simde__m128i *)&rex::ppc::VectorMaskL[k * 16]); }
#define DCBZL(a) memset(base + ((u32)(a) & ~127u), 0, 128)
#define LVX(a) simde_mm_castsi128_ps(simde_mm_shuffle_epi8( \
    simde_mm_load_si128((const simde__m128i *)(base + ((u32)(a) & ~0xFu))), rwp_mask(0)))
#define LVLX(a) simde_mm_castsi128_ps(simde_mm_shuffle_epi8( \
    simde_mm_load_si128((const simde__m128i *)(base + ((u32)(a) & ~0xFu))), rwp_mask((u32)(a) & 0xFu)))
#define STVX(a, v) simde_mm_store_si128((simde__m128i *)(base + ((u32)(a) & ~0xFu)), \
    simde_mm_shuffle_epi8(simde_mm_castps_si128(v), rwp_mask(0)))

// ---- float mode: the recomp's cached VMX (flush) / FPU switch --------------------------------
#define FLUSH_V() ctx.fpscr.enableFlushMode()
#define FLUSH_F() ctx.fpscr.disableFlushMode()

// ---- condition register ------------------------------------------------------------------
enum { CR_LT = 8, CR_GT = 4, CR_EQ = 2, CR_SO = 1 };
static inline u32 CMP_S(s32 a, s32 b) { return a < b ? CR_LT : a > b ? CR_GT : CR_EQ; }
static inline u32 CMP_U(u32 a, u32 b) { return a < b ? CR_LT : a > b ? CR_GT : CR_EQ; }
static inline u32 CMP_F(double a, double b) { return a < b ? CR_LT : a > b ? CR_GT : a == b ? CR_EQ : CR_SO; }
static inline u32 VCR6(__vector4 m)
{
    int bits = simde_mm_movemask_ps(m);
    return (bits == 0xF ? CR_LT : 0) | (bits == 0 ? CR_EQ : 0);
}
#define CRWORD6(cr) ((u32)(cr) << 4)
static inline u32 RLWINM(u32 x, int sh, int mb, int me)
{
    u32 r = sh ? (x << sh) | (x >> (32 - sh)) : x;
    u32 m = mb <= me ? (0xffffffffu >> mb) & (0xffffffffu << (31 - me))
                     : (0xffffffffu >> mb) | (0xffffffffu << (31 - me));
    return r & m;
}
#define FMA_D(a, b, c) std::fma(a, b, c)
static inline double FABS_D(double x) { return std::fabs(x); }

// ---- VMX ops, lowered exactly as the recompiler does ---------------------------------------
#define VZERO simde_mm_setzero_ps()
#define RWP_I(v) simde_mm_castps_si128(v)
#define RWP_F(v) simde_mm_castsi128_ps(v)
static inline __vector4 __vaddfp(__vector4 a, __vector4 b) { return simde_mm_add_ps(a, b); }
static inline __vector4 __vsubfp(__vector4 a, __vector4 b) { return simde_mm_sub_ps(a, b); }
static inline __vector4 __vmulfp(__vector4 a, __vector4 b) { return simde_mm_mul_ps(a, b); }
static inline __vector4 __vmaddfp(__vector4 a, __vector4 b, __vector4 c) { return simde_mm_fmadd_ps(a, b, c); }
static inline __vector4 __vnmsubfp(__vector4 a, __vector4 b, __vector4 c) { return simde_mm_fnmadd_ps(a, b, c); }
static inline __vector4 __vmaxfp(__vector4 a, __vector4 b) { return simde_mm_max_ps(a, b); }
static inline __vector4 __vminfp(__vector4 a, __vector4 b) { return simde_mm_min_ps(a, b); }
static inline __vector4 __vrefp(__vector4 a) { return simde_mm_div_ps(simde_mm_set1_ps(1.0f), a); }
static inline __vector4 __vrsqrtefp(__vector4 a) { return rex::ppc::simde_mm_vrsqrtefp_ps(a); }
static inline __vector4 __vmsum3fp(__vector4 a, __vector4 b) { return rex::ppc::simde_mm_vmsum3fp128_ps(a, b); }
static inline __vector4 __vmsum4fp(__vector4 a, __vector4 b) { return rex::ppc::simde_mm_vmsum4fp128_ps(a, b); }
static inline __vector4 __vcmpgefp(__vector4 a, __vector4 b) { return simde_mm_cmpge_ps(a, b); }
static inline __vector4 __vcmpgtfp(__vector4 a, __vector4 b) { return simde_mm_cmpgt_ps(a, b); }
static inline __vector4 __vcmpeqfp(__vector4 a, __vector4 b) { return simde_mm_cmpeq_ps(a, b); }
static inline __vector4 __vcmpequw(__vector4 a, __vector4 b) { return RWP_F(simde_mm_cmpeq_epi32(RWP_I(a), RWP_I(b))); }
static inline __vector4 __vand(__vector4 a, __vector4 b) { return RWP_F(simde_mm_and_si128(RWP_I(a), RWP_I(b))); }
static inline __vector4 __vor(__vector4 a, __vector4 b) { return RWP_F(simde_mm_or_si128(RWP_I(a), RWP_I(b))); }
static inline __vector4 __vxor(__vector4 a, __vector4 b) { return RWP_F(simde_mm_xor_si128(RWP_I(a), RWP_I(b))); }
static inline __vector4 __vnor(__vector4 a, __vector4 b)
{ return RWP_F(simde_mm_xor_si128(simde_mm_or_si128(RWP_I(a), RWP_I(b)), simde_mm_set1_epi32(-1))); }
static inline __vector4 __vsel(__vector4 a, __vector4 b, __vector4 m)
{ return RWP_F(simde_mm_or_si128(simde_mm_andnot_si128(RWP_I(m), RWP_I(a)), simde_mm_and_si128(RWP_I(m), RWP_I(b)))); }
static inline __vector4 __vslw(__vector4 a, __vector4 b)
{ return RWP_F(simde_mm_sllv_epi32(RWP_I(a), simde_mm_and_si128(RWP_I(b), simde_mm_set1_epi32(0x1F)))); }
// vcuxwfp: unsigned words to float, exact (each u32 fits a double), scaled by 2^-s
static inline __vector4 __vcfux(__vector4 a, int s)
{
    alignas(16) uint32_t u[4];
    simde_mm_store_si128((simde__m128i *)u, RWP_I(a));
    double k = std::ldexp(1.0, -s);
    return simde_mm_set_ps((float)(u[3] * k), (float)(u[2] * k), (float)(u[1] * k), (float)(u[0] * k));
}
static inline __vector4 __vcfsx(__vector4 a, int s)
{
    simde__m128 f = simde_mm_cvtepi32_ps(RWP_I(a));
    return s ? simde_mm_mul_ps(f, simde_mm_set1_ps(std::ldexp(1.0f, -s))) : f;
}
static inline __vector4 __vperm(__vector4 a, __vector4 b, __vector4 c)
{ return RWP_F(rex::ppc::simde_mm_perm_epi8_(RWP_I(a), RWP_I(b), RWP_I(c))); }
// merge high/low: the recomp unpacks (b, a) in its reversed layout
static inline __vector4 __vmrghw(__vector4 a, __vector4 b) { return RWP_F(simde_mm_unpackhi_epi32(RWP_I(b), RWP_I(a))); }
static inline __vector4 __vmrglw(__vector4 a, __vector4 b) { return RWP_F(simde_mm_unpacklo_epi32(RWP_I(b), RWP_I(a))); }
#define __vspltisw(n) RWP_F(simde_mm_set1_epi32(n))
#define __vspltisb(n) RWP_F(simde_mm_set1_epi8((int8_t)(n)))

// immediates translated to the reversed layout (host lane h = guest lane 3 - h)
constexpr int rwp_permwi(int imm)
{
    int r = 0;
    for (int h = 0; h < 4; h++) r |= (3 - ((imm >> (6 - 2 * (3 - h))) & 3)) << (2 * h);
    return r;
}
constexpr int rwp_rlimi_perm(int rot)
{
    int r = 0;
    for (int h = 0; h < 4; h++) r |= (3 - ((3 - h + rot) & 3)) << (2 * h);
    return r;
}
#define __vspltw(v, i) RWP_F(simde_mm_shuffle_epi32(RWP_I(v), (3 - (i)) * 0x55))
#define __vpermwi(v, imm) RWP_F(simde_mm_shuffle_epi32(RWP_I(v), rwp_permwi(imm)))
#define __vrlimi(d, b, mask, rot) simde_mm_blend_ps(d, simde_mm_permute_ps(b, rwp_rlimi_perm(rot)), mask)
#define __vsldoi(a, b, sh) RWP_F(simde_mm_alignr_epi8(RWP_I(a), RWP_I(b), 16 - (sh)))
// vmrghh: the recompiler's lowering (operands swapped in the reversed layout)
#define __vmrghh(a, b) RWP_F(simde_mm_unpackhi_epi16(RWP_I(b), RWP_I(a)))
// vaddsws: signed saturating word add (elementwise, as the recompiler's loop)
static inline __vector4 __vaddsws(__vector4 a, __vector4 b)
{
    alignas(16) int32_t x[4], y[4], r[4];
    simde_mm_store_si128((simde__m128i *)x, RWP_I(a));
    simde_mm_store_si128((simde__m128i *)y, RWP_I(b));
    for (int i = 0; i < 4; ++i)
    {
        long long sum = (long long)x[i] + (long long)y[i];
        r[i] = sum > INT32_MAX ? INT32_MAX : sum < INT32_MIN ? INT32_MIN : (int32_t)sum;
    }
    return RWP_F(simde_mm_load_si128((const simde__m128i *)r));
}
// a 16-byte big-endian load from any address (lvlx + lvrx + vor)
static inline __vector4 LVU(const u8 *base, u32 a)
{
    return simde_mm_castsi128_ps(simde_mm_shuffle_epi8(simde_mm_loadu_si128((const simde__m128i *)(base + a)), rwp_mask(0)));
}

}  // namespace rwp
